#include "yuzu/game_companion_catalog.h"

#include <array>

namespace GameCompanion {
namespace {

#define WIKI "https://axiom-verge.fandom.com/wiki/"

// Axiom Verge 2 (2021). Written for Kaichii from the Axiom Verge Wiki on Fandom, which covers both
// games: only pages about the second game, or the second game's half of shared pages, are used
// here. Names stay in English, as the game shows them.
constexpr std::array Entries{
    // Places
    Entry{"antarctica", Kind::Place, {"Antarctica", "Antártida"},
          {"Where the game begins: an abandoned Hammond Corp station.",
           "Donde empieza el juego: una estación abandonada de Hammond Corp."},
          {"Indra arrives by helicopter, flown by Stan, to inspect the station her company bought from Hammond Corp. The Ice Axe hangs in a shed to the left of the helicopter. Restoring power leads to a one-way elevator that takes her to Kiengir.",
           "Indra llega en helicóptero, pilotado por Stan, para inspeccionar la estación que su empresa compró a Hammond Corp. El Ice Axe está en un cobertizo a la izquierda del helicóptero. Al devolver la energía llega a un ascensor sin retorno que la lleva a Kiengir."},
          WIKI "Indra", false},
    Entry{"the_glacier", Kind::Place, {"The Glacier", "The Glacier (el glaciar)"},
          {"The first area of Kiengir: ice, rock and Hammond's ruined station.",
           "La primera zona de Kiengir: hielo, roca y la estación en ruinas de Hammond."},
          {"Indra finds the Compass, then Amashilama in an urn, which saves her life; then the Gishru boomerang and Sheshkala, who lets her pull herself up ledges. The Breach Attractor is here too, but only reachable late. The Breach version of the Glacier is one of the last places to explore and much harder, with the optional boss Ellag.",
           "Indra encuentra la Compass y después a Amashilama en una urna, que le salva la vida; luego el bumerán Gishru y a Sheshkala, que le permite agarrarse a los salientes. Aquí está también el Breach Attractor, aunque solo se alcanza muy tarde. La versión de la Brecha del glaciar es de los últimos lugares por explorar y mucho más difícil, con el jefe opcional Ellag."},
          WIKI "The_Glacier", false},
    Entry{"mount_ebih", Kind::Place, {"Mount Ebih", "Mount Ebih (monte Ebih)"},
          {"A green mountain with Hammond's camp, the first boss and several key Arms.",
           "Una montaña verde con el campamento de Hammond, el primer jefe y varios Arms clave."},  // codespell:ignore varios
          {"At its foot lies the camp of Hammond Corp's stranded team, where Malka waits; at the peak, Warren works in a research observatory. The first boss, An-Alu, lives here. Mount Ebih holds Mushhus (hacking), Rah (charged melee) and Damu, a child Arm who lets Indra use a drone, next to a Breach portal. The Bronze Axe and the Diviner's Gem come later.",
           "A sus pies está el campamento del equipo varado de Hammond Corp, donde espera Malka; en la cima, Warren trabaja en un observatorio. Aquí vive el primer jefe, An-Alu. El monte Ebih guarda a Mushhus (hackeo), Rah (ataque cuerpo a cuerpo cargado) y Damu, un Arm niño que permite a Indra usar un dron, junto a un portal de la Brecha. El Bronze Axe y la Diviner's Gem llegan más tarde."},
          WIKI "Mount_Ebih", false},
    Entry{"lake_amagi", Kind::Place, {"Lake Amagi", "Lake Amagi (lago Amagi)"},
          {"A sunken city underwater; by then Indra no longer needs to breathe.",
           "Una ciudad sumergida; para entonces Indra ya no necesita respirar."},
          {"Liru makes moving and jumping underwater much easier, and Gud An-Na, at the end of the western tunnels, lets Indra explode in a shockwave. Those tunnels are home to the optional Mus-A-M20. The Breach version of the lake is calmer and holds Halam and the Halusan.",  // codespell:ignore gud
           "Liru facilita mucho moverse y saltar bajo el agua, y Gud An-Na, al final de los túneles del oeste, permite a Indra estallar en una onda expansiva. Esos túneles son el hogar del opcional Mus-A-M20. La versión de la Brecha del lago es más tranquila y guarda a Halam y el Halusan."},  // codespell:ignore gud
          WIKI "Lake_Amagi", false},
    Entry{"giguna_steppes", Kind::Place, {"Giguna Steppes", "Giguna Steppes (estepas de Giguna)"},
          {"Tiered grasslands climbing to rocky peaks, carved with images of the Lamassu.",
           "Llanuras escalonadas que suben a cumbres rocosas, talladas con imágenes del Lamassu."},
          {"Here Indra meets the Lamassu near an old school it ordered built. Ninhursag gives wall climbing; the Double Axe, Sickle Sword, Carnelian Ring and a Power Matrix are here too, and Kari waits in what was Clifftown. The Breach version holds Nano Lattice 1, Eskiri and Usan Rah.",
           "Aquí Indra conoce al Lamassu junto a una antigua escuela que mandó construir. Ninhursag da la escalada de paredes; también están el Double Axe, la Sickle Sword, el Carnelian Ring y una Power Matrix, y Kari espera en lo que fue Clifftown. La versión de la Brecha guarda el Nano Lattice 1, Eskiri y Usan Rah."},
          WIKI "Giguna_Steppes", false},
    Entry{"irikar", Kind::Place, {"Irikar", "Irikar"},
          {"A rival nation of white sand and empty cities with towering spires.",
           "Una nación rival de arena blanca y ciudades vacías con agujas altísimas."},
          {"Once an enemy of the Sagiga and a target of their weapons tests, Irikar stretches from the steppes down to a wide western sea. It holds the Royal Dagger, Ki'Inimak (to see hidden Breach portals), a Power Matrix behind a code read with Ki'Inimak, and possibly Dun. Its Breach version holds Barash.",
           "Antigua enemiga de los Sagiga y blanco de sus pruebas de armas, Irikar se extiende desde las estepas hasta un amplio mar al oeste. Guarda la Royal Dagger, a Ki'Inimak (para ver portales ocultos de la Brecha), una Power Matrix tras un código que se lee con Ki'Inimak y, quizá, a Dun. Su versión de la Brecha guarda a Barash."},
          WIKI "Irikar", false},
    Entry{"uhrum_valley", Kind::Place, {"Uhrum Valley", "Uhrum Valley (valle de Uhrum)"},
          {"A rainy green valley full of hidden gun traps, with a Kazakh base.",
           "Un valle verde y lluvioso lleno de trampas con armas ocultas, con una base kazaja."},
          {"Hidden Gatling guns and cannons fire from a distance. The old Kazakh base houses the portal to the Emergence. Anuman (switch between drone and humanoid), Ensi's Bracelet, a Power Matrix and possibly Dun are here; the Udusan waits in its Breach version.",
           "Ametralladoras y cañones ocultos disparan desde lejos. La antigua base kazaja alberga el portal a The Emergence. Aquí están Anuman (cambiar entre dron y humanoide), el Ensi's Bracelet, una Power Matrix y, quizá, Dun; el Udusan espera en su versión de la Brecha."},
          WIKI "Uhrum_Valley", false},
    Entry{"anunna_gorge", Kind::Place, {"Anunna Gorge", "Anunna Gorge (garganta de Anunna)"},
          {"A vast mechanical gorge, 'the home of the gods', once a war factory.",
           "Una enorme garganta mecánica, «el hogar de los dioses», antigua fábrica de guerra."},
          {"Tall buildings are carved into the rock, with watery caves at the bottom and cliffs up to the Glacier. It holds Tilhar, Nano Lattice 2, the Eye Ring for seeing in the dark, the Royal Ring, the An Gishru and the Ul Gishru, and has more save shrines than anywhere else. A huge yellow Udug Xul drifts through its south-eastern caverns: it cannot be harmed, but it does not hunt Indra.",
           "Altos edificios tallados en la roca, con cuevas inundadas en el fondo y acantilados que suben al glaciar. Guarda a Tilhar, el Nano Lattice 2, el Eye Ring para ver en la oscuridad, el Royal Ring, el An Gishru y el Ul Gishru, y tiene más santuarios de guardado que ningún otro lugar. Un enorme Udug Xul amarillo flota por sus cavernas del sureste: no se le puede dañar, pero no persigue a Indra."},
          WIKI "Anunna_Gorge", false},
    Entry{"the_emergence", Kind::Place, {"The Emergence", "The Emergence"},
          {"Another world, reached through a portal in Uhrum Valley.",
           "Otro mundo, al que se llega por un portal en el valle de Uhrum."},
          {"Drushka and her guards live behind a barrier here, where time runs slower than in the worlds around it. Its harmless creatures look like smaller cousins of Sudra's. Talking to Drushka earns the Imdug Bir.",
           "Drushka y sus guardias viven aquí tras una barrera, donde el tiempo corre más despacio que en los mundos de alrededor. Sus criaturas inofensivas parecen primas pequeñas de las de Sudra. Hablar con Drushka da el Imdug Bir."},
          WIKI "The_Emergence", false},
    Entry{"breach_world", Kind::Place, {"The Breach", "La Brecha (Breach)"},
          {"A second, glitched version of every area, explored as a drone.",
           "Una segunda versión, llena de glitches, de cada zona, que se explora como dron."},
          {"Once Damu lets Indra use a drone, she can enter Breach portals and explore the Breach counterpart of each land, where many Arms and upgrades hide. Ki'Inimak shows hidden portals, often on altars engraved with the worldstream; Halam lets her leave the Breach anywhere; the Breach Attractor pulls portals toward her.",
           "Cuando Damu permite a Indra usar un dron, puede entrar en los portales de la Brecha y explorar la versión de la Brecha de cada tierra, donde se esconden muchos Arms y mejoras. Ki'Inimak muestra los portales ocultos, a menudo en altares grabados con la corriente de mundos; Halam le permite salir de la Brecha en cualquier punto; el Breach Attractor atrae los portales hacia ella."},
          WIKI "Breach", false},

    // Characters
    Entry{"indra", Kind::Character, {"Indra Chaudhari", "Indra Chaudhari"},
          {"A billionaire searching for her daughter in a strange alternate world.",
           "Una multimillonaria que busca a su hija en un extraño mundo alternativo."},
          {"Head of the Globe 3 conglomerate, which bought Hammond Corp. She travels to its abandoned Antarctic base and is carried to Kiengir, where she learns to fight and gathers Arms, Sagiga turned into nanomachines that give her new powers. Early on she reveals she is looking for her daughter, Samara.",
           "Dirige el conglomerado Globe 3, que compró Hammond Corp. Viaja a su base abandonada en la Antártida y acaba en Kiengir, donde aprende a luchar y reúne Arms, sagiga convertidos en nanomáquinas que le dan nuevos poderes. Pronto revela que busca a su hija, Samara."},
          WIKI "Indra", false},
    Entry{"amashilama", Kind::Character, {"Amashilama", "Amashilama"},
          {"The first Arm, who heals Indra and becomes her mentor.",
           "El primer Arm, que cura a Indra y se convierte en su mentora."},
          {"Found in an urn in the Glacier. Indra drowns reaching her and Amashilama revives her, then lives in her head, explaining Arms and Kiengir's technology. Once a student named Elutil, she became an Arm during the Udug War, bound to the scholar Mageshgetil.",
           "Está en una urna del glaciar. Indra se ahoga al llegar hasta ella y Amashilama la revive; después vive en su cabeza y le explica los Arms y la tecnología de Kiengir. Antes fue una estudiante llamada Elutil y se convirtió en Arm durante la guerra contra los Udug, ligada al erudito Mageshgetil."},
          WIKI "Amashilama", false},
    Entry{"damu", Kind::Character, {"Damu", "Damu"},
          {"A child Arm who gives Indra her drone, and her closest friend.",
           "Un Arm niño que da a Indra su dron, y su amigo más cercano."},
          {"Found next to a Breach portal on Mount Ebih. Indra is shocked that he is a child and feels for him, trapped in an urn since the war. He was made an Arm because a young mind was thought more adaptable, then cast aside when the war ended. His drone lets Indra explore the Breach.",
           "Está junto a un portal de la Brecha en el monte Ebih. A Indra le impacta que sea un niño y le da pena, atrapado en una urna desde la guerra. Lo convirtieron en Arm porque se creía que una mente joven se adaptaría mejor, y lo apartaron al terminar la guerra. Su dron permite a Indra explorar la Brecha."},
          WIKI "Damu", false},
    Entry{"lamassu", Kind::Character, {"The Lamassu", "El Lamassu"},
          {"A god-like guardian machine that the people of Kiengir obeyed.",
           "Una máquina guardiana casi divina a la que obedecía la gente de Kiengir."},
          {"It takes the form of a winged bull so Kiengir's people could relate to it. They revered it and followed every order: schools, bridges, and finally weapons for the war against the Udug. Indra first meets it in the Giguna Steppes; afterwards it speaks through terminals across the land and wants the Arms destroyed.",  // codespell:ignore revered
           "Adopta la forma de un toro alado para que la gente de Kiengir se identificara con él. Lo veneraban y cumplían todas sus órdenes: escuelas, puentes y, al final, armas para la guerra contra los Udug. Indra lo conoce en las estepas de Giguna; después habla a través de terminales repartidos por el territorio y quiere que se destruyan los Arms."},
          WIKI "Lamassu", false},
    Entry{"hammond_team", Kind::Character, {"Hammond's team", "El equipo de Hammond"},
          {"Malka, Warren and Kari: the stranded survivors of Hammond Corp's expedition.",
           "Malka, Warren y Kari: los supervivientes varados de la expedición de Hammond Corp."},
          {"Malka, at the camp on Mount Ebih, explains the basics of Kiengir. Warren, the site manager, tries to build a portal home in the mountain-top observatory, but it needs an ansible they lack. Kari, in the Giguna Steppes, wants to go home and admires Indra's independence. See the warning card about touching them later in the game.",
           "Malka, en el campamento del monte Ebih, explica lo básico de Kiengir. Warren, el jefe del emplazamiento, intenta construir un portal de vuelta en el observatorio de la cima, pero necesita un ansible que no tienen. Kari, en las estepas de Giguna, quiere volver a casa y admira la independencia de Indra. Consulta la ficha de advertencia sobre tocarlos más adelante."},
          WIKI "Warren", false},
    Entry{"drushka", Kind::Character, {"Drushka", "Drushka"},
          {"A Kazakh researcher who rules the Emergence and studies evolution.",
           "Una investigadora kazaja que gobierna The Emergence y estudia la evolución."},
          {"Zhansaya Korshunova, known as Drushka, came to Kiengir with a Kazakh team allied with Hammond Corp. Trapped there, they stole an ansible and some fled to the Emergence, where she speeds the passage of time to watch evolution and wants to steer humanity's. She is named in two notes of the first Axiom Verge.",
           "Zhansaya Korshunova, conocida como Drushka, llegó a Kiengir con un equipo kazajo aliado con Hammond Corp. Atrapados allí, robaron un ansible y algunos huyeron a The Emergence, donde acelera el paso del tiempo para observar la evolución y quiere guiar la de la humanidad. Aparece mencionada en dos notas del primer Axiom Verge."},
          WIKI "Drushka", false},
    Entry{"mageshgetil", Kind::Character, {"Mageshgetil", "Mageshgetil"},
          {"A heretic scholar and Amashilama's Wielder, known from his writings.",
           "Un erudito hereje y portador de Amashilama, conocido por sus escritos."},
          {"He questioned the Lamassu's holiness and believed A'ansur held its worlds back. Bound to Amashilama, he wrote letters urging Kiengir's people to think for themselves; later he separated from her and hid her away. Elutil's letters to her brother Ludari tell the same story from her side.",
           "Cuestionaba la santidad del Lamassu y creía que A'ansur frenaba a sus mundos. Ligado a Amashilama, escribió cartas pidiendo a la gente de Kiengir que pensara por sí misma; más tarde se separó de ella y la escondió. Las cartas de Elutil a su hermano Ludari cuentan la misma historia desde su lado."},
          WIKI "Mageshgetil", false},

    // Bosses
    Entry{"an_alu", Kind::Boss, {"An-Alu", "An-Alu"},
          {"The first boss, on Mount Ebih.",
           "El primer jefe, en el monte Ebih."},
          {"Defeating it gives a small Apocalypse Flask. A second An-Alu hides in Anunna Gorge.",
           "Derrotarlo da un Apocalypse Flask pequeño. Un segundo An-Alu se esconde en la garganta de Anunna."},
          WIKI "An-Alu", false},
    Entry{"mus_a_m20", Kind::Boss, {"Mus-A-M20", "Mus-A-M20"},
          {"An optional giant worm in Lake Amagi's western tunnels.",
           "Un gusano gigante opcional en los túneles del oeste del lago Amagi."},
          {"It vents hot steam and chases Indra with an electric cloud. It cannot be hurt directly: use Gud An-Na's shockwave to drop four stalactites on it, anywhere on its body. Kimu nearby refill the nanites the shockwave costs. It drops a medium Apocalypse Flask.",  // codespell:ignore gud
           "Expulsa vapor ardiente y persigue a Indra con una nube eléctrica. No se le puede dañar directamente: usa la onda de Gud An-Na para dejar caer cuatro estalactitas sobre él, en cualquier parte del cuerpo. Los Kimu cercanos recargan los nanites que cuesta la onda. Suelta un Apocalypse Flask mediano."},  // codespell:ignore gud
          WIKI "Mus-A-M20", false},
    Entry{"ellag", Kind::Boss, {"Ellag", "Ellag"},
          {"An optional boss in the Glacier's Breach.",
           "Un jefe opcional en la Brecha del glaciar."},
          {"A shield protects it while a floating panel fires lasers. Break the panel and the shield falls with it, leaving the body open. Watch the big eye: its charged laser can destroy Indra's drone in one hit. It drops a medium Apocalypse Flask.",
           "Un escudo lo protege mientras un panel flotante dispara láseres. Rompe el panel y el escudo cae con él, dejando el cuerpo expuesto. Vigila el gran ojo: su láser cargado puede destruir el dron de Indra de un golpe. Suelta un Apocalypse Flask mediano."},
          WIKI "Ellag", false},
    Entry{"siuna_fight", Kind::Boss, {"Amashilama's Siuna", "La Siuna de Amashilama"},
          {"The final confrontation, beneath the Glacier.",
           "El enfrentamiento final, bajo el glaciar."},
          {"Amashilama, in a Siuna body built for Apocalypse Arms, tries to reach the portal to A'ansur. Indra must fill a Breach bomb at the portal while fighting her; the battle ends with a sacrifice.",
           "Amashilama, en un cuerpo Siuna creado para los Apocalypse Arms, intenta llegar al portal a A'ansur. Indra debe llenar una bomba de la Brecha en el portal mientras lucha con ella; el combate termina con un sacrificio."},
          WIKI "Amashilama", true},

    // Weapons and gear
    Entry{"ice_axe", Kind::Item, {"Ice Axe", "Ice Axe"},
          {"Indra's first weapon, a mountaineering axe.",
           "La primera arma de Indra, un piolet de montañismo."},
          {"In the shed next to the helicopter in Antarctica. It also breaks wood. The Bronze Axe replaces it.",
           "En el cobertizo junto al helicóptero en la Antártida. También rompe madera. El Bronze Axe lo sustituye."},
          WIKI "Ice_Axe", false},
    Entry{"axes", Kind::Item, {"Bronze Axe and Double Axe", "Bronze Axe y Double Axe"},
          {"Stronger axes: a balanced one-handed axe and a slow, heavy two-handed one.",
           "Hachas más fuertes: una equilibrada a una mano y otra lenta y pesada a dos manos."},
          {"The Bronze Axe (Mount Ebih, needs Gud An-Na and Damu) is better than the Ice Axe in every way; with the Carnelian Ring, its charged attack fires a projectile. The Double Axe (Giguna Steppes, guarded by a Gubi, needs hacking level 2) hits hardest; Ensi's Bracelet adds a downward slam.",  // codespell:ignore gud
           "El Bronze Axe (monte Ebih, requiere Gud An-Na y Damu) es mejor que el Ice Axe en todo; con el Carnelian Ring, su ataque cargado lanza un proyectil. El Double Axe (estepas de Giguna, vigilado por un Gubi, requiere hackeo de nivel 2) es el que más pega; el Ensi's Bracelet le añade un golpe hacia abajo."},  // codespell:ignore gud,requiere
          WIKI "Bronze_Axe", false},
    Entry{"fast_blades", Kind::Item, {"Sickle Sword and Royal Dagger", "Sickle Sword y Royal Dagger"},
          {"Faster blades that trade damage for speed.",
           "Hojas más rápidas que cambian daño por velocidad."},
          {"The Sickle Sword is in the Giguna Steppes. The Royal Dagger, in Irikar, is very fast but short; with the Royal Ring it also fires a small projectile while Indra is at full health.",
           "La Sickle Sword está en las estepas de Giguna. La Royal Dagger, en Irikar, es muy rápida pero corta; con el Royal Ring también lanza un pequeño proyectil cuando Indra tiene la salud al máximo."},
          WIKI "Royal_Dagger", false},
    Entry{"gishru", Kind::Item, {"Gishru", "Gishru"},
          {"A boomerang glistening with nanomachines, with two upgrades.",
           "Un bumerán que brilla con nanomáquinas, con dos mejoras."},
          {"Found in the Glacier; it slowly returns after each throw. The An Gishru (Anunna Gorge) can be steered remotely for a while and is needed to open certain doors and reach several flasks. The Ul Gishru (Anunna Gorge, behind a barrier) adds damage when it connects with melee hits.",
           "Está en el glaciar; vuelve despacio tras cada lanzamiento. El An Gishru (garganta de Anunna) se puede dirigir a distancia un tiempo y hace falta para abrir ciertas puertas y alcanzar varios frascos. El Ul Gishru (garganta de Anunna, tras una barrera) añade daño al combinarse con golpes cuerpo a cuerpo."},  // codespell:ignore hace,varios
          WIKI "Gishru", false},
    Entry{"drone_weapons", Kind::Item, {"Drone weapons", "Armas del dron"},
          {"The drone's spinning razor and its upgrades.",
           "La cuchilla giratoria del dron y sus mejoras."},
          {"The Mulusan is the drone's default weapon: a blade on a cord that can curve as you aim. The Udusan, in Uhrum Valley's Breach, replaces it with more reach and damage. With Usan Rah, the Halusan (Lake Amagi's Breach) makes charged drone attacks fire a rolling projectile.",
           "El Mulusan es el arma por defecto del dron: una cuchilla con cordón que se curva al apuntar. El Udusan, en la Brecha del valle de Uhrum, lo sustituye con más alcance y daño. Con Usan Rah, el Halusan (Brecha del lago Amagi) hace que los ataques cargados del dron lancen un proyectil rodante."},  // codespell:ignore hace
          WIKI "Mulusan", false},
    Entry{"compass", Kind::Item, {"Compass and Diviner's Gem", "Compass y Diviner's Gem"},
          {"A pendant that points toward Breach portals and nearby items.",
           "Un colgante que señala portales de la Brecha y objetos cercanos."},
          {"The Compass (Glacier) glows red toward a Breach portal and blue toward a nearby item such as a Health Node or Apocalypse Flask. The Diviner's Gem (Mount Ebih, behind two pink gates; needs Tilhar, Damu and the An Gishru) makes it flash near items.",
           "La Compass (glaciar) brilla en rojo hacia un portal de la Brecha y en azul hacia un objeto cercano, como un nodo de salud o un Apocalypse Flask. La Diviner's Gem (monte Ebih, tras dos puertas rosas; requiere Tilhar, Damu y el An Gishru) hace que destelle cerca de los objetos."},  // codespell:ignore hace,requiere
          WIKI "Compass", false},
    Entry{"rings", Kind::Item, {"Rings and bracelet", "Anillos y brazalete"},
          {"Small upgrades that change how weapons and sight work.",
           "Pequeñas mejoras que cambian las armas y la visión."},
          {"Carnelian Ring (Giguna Steppes, hacking level 3): charged Bronze Axe attacks fire a projectile. Royal Ring (Anunna Gorge, code shown with Ki'Inimak): the Royal Dagger shoots at full health. Eye Ring (Anunna Gorge, hacking level 4): see in the dark without a flashlight. Ensi's Bracelet (Uhrum Valley): a downward slam with the Double Axe.",
           "Carnelian Ring (estepas de Giguna, hackeo nivel 3): el ataque cargado del Bronze Axe lanza un proyectil. Royal Ring (garganta de Anunna, código visible con Ki'Inimak): la Royal Dagger dispara con la salud al máximo. Eye Ring (garganta de Anunna, hackeo nivel 4): ver en la oscuridad sin linterna. Ensi's Bracelet (valle de Uhrum): un golpe hacia abajo con el Double Axe."},
          WIKI "Eye_Ring", false},
    Entry{"nano_lattice", Kind::Item, {"Nano Lattice", "Nano Lattice"},
          {"Three armour upgrades, each cutting damage by 15%.",
           "Tres mejoras de armadura, cada una reduce el daño un 15 %."},
          {"Nano Lattice 1 is in the Giguna Steppes' Breach, 2 in Anunna Gorge and 3 in Anunna Gorge's Breach. They protect both Indra and her drone, and change their colour.",
           "El Nano Lattice 1 está en la Brecha de las estepas de Giguna, el 2 en la garganta de Anunna y el 3 en la Brecha de la garganta de Anunna. Protegen a Indra y a su dron, y cambian su color."},
          WIKI "Nano_Lattice", false},
    Entry{"power_matrix", Kind::Item, {"Power Matrix", "Power Matrix"},
          {"A health bank that heals Indra, refilled with Power Cells.",
           "Un banco de salud que cura a Indra y se rellena con Power Cells."},
          {"There are four: in the Giguna Steppes, in Irikar behind a code shown with Ki'Inimak, in Uhrum Valley, and in Mount Ebih's Breach. Power Cells lie around Kiengir or are carried by some drones. Tip: when low on health, hacking a Power Cell and choosing 'emit health' heals at once and costs nothing.",
           "Hay cuatro: en las estepas de Giguna, en Irikar tras un código visible con Ki'Inimak, en el valle de Uhrum y en la Brecha del monte Ebih. Las Power Cells están repartidas por Kiengir o las llevan algunos drones. Consejo: con poca salud, hackear una Power Cell y elegir «emitir salud» cura al momento y no cuesta nada."},  // codespell:ignore momento
          WIKI "Power_Matrix", false},
    Entry{"breach_attractor", Kind::Item, {"Breach Attractor", "Breach Attractor"},
          {"A late item that pulls Breach portals toward Indra.",
           "Un objeto tardío que atrae los portales de la Brecha hacia Indra."},
          {"Much smaller and humbler than the world-ending device of the first game. It lies in the Glacier and is only reachable late in the game.",
           "Mucho más pequeño y modesto que el dispositivo apocalíptico del primer juego. Está en el glaciar y solo se alcanza al final del juego."},
          WIKI "Breach_Attractor", false},

    // Arms and abilities
    Entry{"sheshkala", Kind::Ability, {"Sheshkala (ledge grab)", "Sheshkala (agarre)"},
          {"Grab ledges and pull yourself up.",
           "Agarrarse a los salientes y subir."},
          {"The second Arm, in the Glacier: a revered leader in life, now letting Indra climb onto ledges.",  // codespell:ignore revered
           "El segundo Arm, en el glaciar: una líder venerada en vida que ahora permite a Indra subir a los salientes."},
          WIKI "Sheshkala", false},
    Entry{"ninhursag", Kind::Ability, {"Ninhursag (wall climbing)", "Ninhursag (escalada)"},
          {"Climb vertical walls.",
           "Escalar paredes verticales."},
          {"Found in the Giguna Steppes. Opens many vertical paths across Kiengir.",
           "Está en las estepas de Giguna. Abre muchos caminos verticales por todo Kiengir."},
          WIKI "Ninhursag", false},
    Entry{"mushhus", Kind::Ability, {"Mushhus (hacking)", "Mushhus (hackeo)"},
          {"Infect enemies and objects to change their behaviour.",
           "Infectar enemigos y objetos para cambiar su comportamiento."},
          {"Found on Mount Ebih. Indra slowly grows a buzzing purple field; any machine inside it can be hacked for nanites. Its icon is a biohazard sign. See the Hacking card.",
           "Está en el monte Ebih. Indra genera poco a poco un campo morado zumbante; cualquier máquina dentro se puede hackear a cambio de nanites. Su icono es el símbolo de riesgo biológico. Consulta la ficha Hackeo."},
          WIKI "Mushhus", false},
    Entry{"rah", Kind::Ability, {"Rah (charged melee)", "Rah (ataque cargado)"},
          {"Hold the attack button to charge melee strikes.",
           "Mantén el botón de ataque para cargar los golpes."},
          {"Found inside a building on Mount Ebih. Charged hits strike harder, and some rings add projectiles to them.",
           "Está dentro de un edificio del monte Ebih. Los golpes cargados pegan más fuerte, y algunos anillos les añaden proyectiles."},
          WIKI "Rah", false},
    Entry{"damu_drone", Kind::Ability, {"Damu (remote drone)", "Damu (dron remoto)"},
          {"Launch a drone you can control, and detonate it to return to Indra.",
           "Lanzar un dron controlable y detonarlo para volver con Indra."},  // codespell:ignore controlable
          {"The drone fits small spaces and is the only way to enter the Breach. Many later Arms upgrade it: Eskiri, Barash, Usan Rah, Imdug Bir and Zal Tu.",
           "El dron cabe en espacios pequeños y es la única forma de entrar en la Brecha. Muchos Arms posteriores lo mejoran: Eskiri, Barash, Usan Rah, Imdug Bir y Zal Tu."},
          WIKI "Damu", false},
    Entry{"dun", Kind::Ability, {"Dun (fast travel)", "Dun (viaje rápido)"},
          {"Travel between save shrines from the map screen.",
           "Viajar entre santuarios de guardado desde el mapa."},
          {"It is in either Uhrum Valley or Irikar, whichever Indra reaches first; it cannot be taken twice.",
           "Está en el valle de Uhrum o en Irikar, en el que Indra visite primero; no se puede obtener dos veces."},
          WIKI "Dun", false},
    Entry{"tilhar", Kind::Ability, {"Tilhar (nanite cloud)", "Tilhar (nube de nanites)"},
          {"Turn into a cloud of nanites to pass through grates.",
           "Convertirse en una nube de nanites para atravesar rejillas."},
          {"Found at the top of the room in Anunna Gorge where Amashilama's Siuna first appears. The cloud's speed can be raised in Skills.",
           "Está en lo alto de la sala de la garganta de Anunna donde aparece por primera vez la Siuna de Amashilama. La velocidad de la nube se mejora en Habilidades."},
          WIKI "Tilhar", false},
    Entry{"liru", Kind::Ability, {"Liru (swimming)", "Liru (natación)"},
          {"Move and jump freely underwater.",
           "Moverse y saltar con libertad bajo el agua."},
          {"Found in Lake Amagi: normal running speed and a much higher jump underwater.",
           "Está en el lago Amagi: velocidad normal y un salto mucho más alto bajo el agua."},
          WIKI "Liru", false},
    Entry{"gud_an_na", Kind::Ability, {"Gud An-Na (shockwave)", "Gud An-Na (onda expansiva)"},  // codespell:ignore gud
          {"Explode into a shockwave that shakes the earth.",
           "Estallar en una onda expansiva que sacude la tierra."},
          {"At the end of the Mus-A-M20's tunnels in Lake Amagi. It damages enemies and knocks down fragile rocks and stalactites, costing 100 nanites; a Kimu is usually nearby where it is needed.",
           "Al final de los túneles del Mus-A-M20 en el lago Amagi. Daña enemigos y derriba rocas frágiles y estalactitas, y cuesta 100 nanites; suele haber un Kimu cerca donde hace falta."},  // codespell:ignore hace
          WIKI "Gud_An-Na", false},
    Entry{"ki_inimak", Kind::Ability, {"Ki'Inimak (Breach sight)", "Ki'Inimak (vista de la Brecha)"},
          {"See into the Breach and enter hidden portals; also reveals secret codes.",
           "Ver dentro de la Brecha y entrar en portales ocultos; también revela códigos secretos."},
          {"Found in Irikar. Hidden portals may be on altars or in unremarkable spots. It also shows arrow codes on walls, such as the ones for a Power Matrix in Irikar and the Royal Ring in Anunna Gorge.",
           "Está en Irikar. Los portales ocultos pueden estar en altares o en lugares anodinos. También muestra códigos de flechas en las paredes, como los de una Power Matrix en Irikar y el Royal Ring en la garganta de Anunna."},
          WIKI "Ki%27Inimak", false},
    Entry{"halam", Kind::Ability, {"Halam (Breach exit)", "Halam (salida de la Brecha)"},
          {"Leave the Breach at any point.",
           "Salir de la Brecha en cualquier punto."},
          {"Found in Lake Amagi's Breach. Exiting where you choose can bypass gates and reach secret rooms on Kiengir.",
           "Está en la Brecha del lago Amagi. Salir donde quieras permite saltarse puertas y llegar a salas secretas de Kiengir."},
          WIKI "Halam", false},
    Entry{"anuman", Kind::Ability, {"Anuman (transformation)", "Anuman (transformación)"},
          {"Switch freely between drone and humanoid form.",
           "Cambiar libremente entre dron y forma humanoide."},
          {"Found in Uhrum Valley.",
           "Está en el valle de Uhrum."},
          WIKI "Anuman", false},
    Entry{"drone_arms", Kind::Ability, {"Drone Arms", "Arms del dron"},
          {"Eskiri, Barash, Usan Rah, Imdug Bir and Zal Tu.",
           "Eskiri, Barash, Usan Rah, Imdug Bir y Zal Tu."},
          {"Eskiri (Giguna Steppes' Breach) fires a hook that slingshots the drone over ledges; Imdug Bir (from Drushka in the Emergence) lets you charge that slingshot and launch it at enemies; Zal Tu (Mount Ebih's Breach) makes the launched drone spin as a weapon. Barash (Irikar's Breach) lets the drone hover with wings. Usan Rah (Giguna Steppes' Breach) charges drone attacks.",
           "Eskiri (Brecha de las estepas de Giguna) lanza un gancho que impulsa el dron sobre los salientes; Imdug Bir (de Drushka, en The Emergence) permite cargar ese impulso y lanzarlo contra enemigos; Zal Tu (Brecha del monte Ebih) hace que el dron lanzado gire como un arma. Barash (Brecha de Irikar) permite al dron flotar con alas. Usan Rah (Brecha de las estepas de Giguna) carga los ataques del dron."},  // codespell:ignore hace
          WIKI "Eskiri", false},

    // Tips and mechanics
    Entry{"hacking", Kind::Guide, {"Hacking", "Hackeo"},
          {"Turn enemies into allies, open gates and more, for nanites.",
           "Convertir enemigos en aliados, abrir puertas y más, a cambio de nanites."},
          {"After Mushhus, Indra grows a field around her; machines and some objects inside it can be hacked. Each one offers its own options: make it an ally, slow it, break part of it, open a gate, emit health, and so on. Gates and better options need higher hacking levels, raised in Skills. Living creatures such as the Udug cannot be hacked. Kimu, found near places that need it, slowly give 100 nanites.",
           "Tras Mushhus, Indra genera un campo a su alrededor; las máquinas y algunos objetos dentro se pueden hackear. Cada uno ofrece sus opciones: convertirlo en aliado, ralentizarlo, romperle una parte, abrir una puerta, emitir salud, etc. Las puertas y las mejores opciones requieren niveles de hackeo más altos, que se suben en Habilidades. Las criaturas vivas, como los Udug, no se pueden hackear. Los Kimu, cerca de los lugares que lo necesitan, dan poco a poco 100 nanites."},
          WIKI "Hacking", false},
    Entry{"skills", Kind::Guide, {"Skills and Apocalypse Flasks", "Habilidades y Apocalypse Flasks"},
          {"How Indra grows stronger.",
           "Cómo se hace más fuerte Indra."},  // codespell:ignore hace
          {"Apocalypse Flasks give skill points: small ones one, medium ones two (there are no large ones). Spend them in Skills: Physiology (health, nanite cloud speed), Combat (damage and attack speed), Infection (hacking level and field) and Drone (drone damage and speed). Categories unlock as you find Mushhus, Damu and other Arms. Health Nodes add health on top of that.",
           "Los Apocalypse Flasks dan puntos de habilidad: los pequeños uno y los medianos dos (no hay grandes). Se gastan en Habilidades: Fisiología (salud, velocidad de la nube de nanites), Combate (daño y velocidad de ataque), Infección (nivel y campo de hackeo) y Dron (daño y velocidad del dron). Las categorías se desbloquean al encontrar a Mushhus, Damu y otros Arms. Los nodos de salud añaden salud aparte."},
          WIKI "Skills", false},
    Entry{"save_shrines", Kind::Guide, {"Save Shrines", "Santuarios de guardado"},
          {"Hourglass-shaped pedestals where Indra saves and reforms after death.",
           "Pedestales con forma de reloj de arena donde Indra guarda y se recompone al morir."},
          {"Unlike Sudra's Rebirth Chambers they have no room of their own, so enemies can still attack while you stand on one. Indra reforms from a cloud of nanites at the last one used. With Dun you can travel between them from the map. Most areas have three or more; the Glacier has one, Anunna Gorge eight.",
           "A diferencia de las cámaras de renacimiento de Sudra, no tienen sala propia, así que los enemigos pueden atacar mientras estás encima. Indra se recompone desde una nube de nanites en el último usado. Con Dun puedes viajar entre ellos desde el mapa. Casi todas las zonas tienen tres o más; el glaciar tiene uno y la garganta de Anunna, ocho."},
          WIKI "Save_Shrine", false},
    Entry{"infection_warning", Kind::Guide, {"Careful with the survivors", "Cuidado con los supervivientes"},
          {"Touching the stranded humans late in the game has consequences.",
           "Tocar a los humanos varados más avanzado el juego tiene consecuencias."},
          {"After Indra gets Damu and enters the Breach, physical contact with Malka, Warren or Kari infects them. About two hours later they turn into a Proto-Xedur, a small version of the first game's first boss, which must be fought and is gone for good. Keep your distance if you want them to stay as they are.",
           "Cuando Indra consigue a Damu y entra en la Brecha, el contacto físico con Malka, Warren o Kari los infecta. Unas dos horas después se convierten en un Proto-Xedur, una versión pequeña del primer jefe del primer juego, al que hay que combatir y que desaparece para siempre. Mantén la distancia si quieres que sigan como están."},
          WIKI "Proto-Xedur", false},
    Entry{"exploring", Kind::Guide, {"Finding your way", "Orientarse"},
          {"How to find the next step in a world with no fixed order.",
           "Cómo encontrar el siguiente paso en un mundo sin orden fijo."},
          {"The map is divided into sectors, and most items have a fixed sector. The Compass and Diviner's Gem point to portals and items nearby. When stuck, check which Arm you lack: Ninhursag for walls, Liru for water, Tilhar for grates, Ki'Inimak for hidden portals, Halam to leave the Breach anywhere. Hacking gates need a higher level from Skills.",
           "El mapa se divide en sectores, y la mayoría de objetos tienen un sector fijo. La Compass y la Diviner's Gem señalan portales y objetos cercanos. Si te atascas, revisa qué Arm te falta: Ninhursag para paredes, Liru para el agua, Tilhar para rejillas, Ki'Inimak para portales ocultos, Halam para salir de la Brecha donde quieras. Las puertas de hackeo requieren un nivel más alto en Habilidades."},
          WIKI "Axiom_Verge_2", false},

    // Story and lore
    Entry{"kiengir", Kind::Timeline, {"Kiengir", "Kiengir"},
          {"The world of the game: an earth-like land shaped like a torus.",
           "El mundo del juego: una tierra parecida a la Tierra con forma de toro."},
          {"Blue skies, green grass and ruined cities, modelled on ancient Sumer. Its people, the Sagiga, are gone; what moves now are mostly drones obeying the Lamassu. Breach entrances are everywhere, some in plain sight and others hidden.",
           "Cielos azules, hierba verde y ciudades en ruinas, inspiradas en la antigua Sumeria. Su pueblo, los Sagiga, ya no está; lo que se mueve ahora son sobre todo drones que obedecen al Lamassu. Hay entradas a la Brecha por todas partes, unas a la vista y otras ocultas."},
          WIKI "Kiengir", false},
    Entry{"sagiga", Kind::Timeline, {"The Sagiga", "Los Sagiga"},
          {"Kiengir's vanished people, human in appearance.",
           "El pueblo desaparecido de Kiengir, de aspecto humano."},
          {"A religious monarchy that revered the Lamassu and wrote in a cuneiform-like script. The only Sagiga left are the Arms. Their notes, translated as Indra reads them, tell of schools, heresies and war.",  // codespell:ignore revered
           "Una monarquía religiosa que veneraba al Lamassu y escribía con una escritura parecida a la cuneiforme. Los únicos Sagiga que quedan son los Arms. Sus notas, que se traducen al leerlas, hablan de escuelas, herejías y guerra."},
          WIKI "Sagiga_(People)", false},
    Entry{"udug_war", Kind::Timeline, {"The Udug War and the Arms", "La guerra contra los Udug y los Arms"},
          {"Why Kiengir is empty and its people became weapons.",
           "Por qué Kiengir está vacío y su gente se convirtió en armas."},
          {"Demons called Udug came from the Breach. The Lamassu ordered the Sagiga to build defences, then weapons such as storm bombs, and finally Arms: first pure nanotechnology, then living people turned into nanomachines bound to Wielders. After the war, the Lamassu ordered all war technology destroyed; Arms without a Wielder were hidden or buried, which is how Indra finds them in urns.",
           "Unos demonios llamados Udug llegaron desde la Brecha. El Lamassu ordenó a los Sagiga construir defensas, después armas como las bombas de tormenta y, por último, Arms: primero nanotecnología pura y luego personas convertidas en nanomáquinas ligadas a portadores. Tras la guerra, el Lamassu ordenó destruir toda la tecnología bélica; los Arms sin portador se escondieron o enterraron, y así los encuentra Indra en urnas."},
          WIKI "Timeline", false},
    Entry{"a_ansur", Kind::Timeline, {"A'ansur", "A'ansur"},
          {"The holy mother world from which Kiengir and countless others branch.",
           "El sagrado mundo madre del que surgen Kiengir y otros incontables."},
          {"Pictured as a tree whose branches are worlds that cannot exist without it. Most of Kiengir revered it; skeptics such as Mageshgetil and Elutil believed it held its worlds back and wanted them set free.",  // codespell:ignore revered
           "Se representa como un árbol cuyas ramas son mundos que no pueden existir sin él. Casi todo Kiengir lo veneraba; escépticos como Mageshgetil y Elutil creían que frenaba a sus mundos y querían liberarlos."},
          WIKI "A%27ansur", false},
    Entry{"story_start", Kind::Timeline, {"The story so far", "La historia hasta ahora"},
          {"The premise, without spoilers.",
           "El planteamiento, sin spoilers."},
          {"Globe 3 has bought Hammond Corp, and Indra travels to its abandoned Antarctic base to see what was left behind. An elevator takes her to Kiengir, where Amashilama saves her and guides her, and the Lamassu watches. Meanwhile she looks for her daughter, Samara, and for the truth about Hammond's expedition and this world.",
           "Globe 3 ha comprado Hammond Corp, e Indra viaja a su base abandonada en la Antártida para ver qué quedó. Un ascensor la lleva a Kiengir, donde Amashilama la salva y la guía mientras el Lamassu observa. Entretanto busca a su hija, Samara, y la verdad sobre la expedición de Hammond y este mundo."},
          WIKI "Axiom_Verge_2", false},
    Entry{"story_full", Kind::Timeline, {"The whole story", "La historia completa"},
          {"Everything that happens, including the ending.",
           "Todo lo que ocurre, final incluido."},
          {"After the Lamassu says the Arms should be disposed of, Amashilama urges Indra to use a machine that splits her mind between body and drone. It is a trap: Amashilama takes Indra's body and runs off to seek the Siuna, intending to destroy A'ansur. Indra, now a drone, follows her with the Lamassu's help. Amashilama abandons Indra's body for a Siuna and heads for the portal to A'ansur beneath the Glacier. In the final fight, Indra's own body arrives to hold Amashilama down while Indra sets off a Breach bomb, destroying them both. Left as a drone on Kiengir, Indra resolves to find a way to give Damu a real body again. A secret post-credits scene shows the Indra who sacrificed herself reunited with Samara and Hammond.",
           "Cuando el Lamassu dice que habría que deshacerse de los Arms, Amashilama convence a Indra de usar una máquina que divide su mente entre el cuerpo y el dron. Es una trampa: Amashilama se queda con el cuerpo de Indra y huye en busca de la Siuna para destruir A'ansur. Indra, ahora un dron, la persigue con ayuda del Lamassu. Amashilama abandona el cuerpo de Indra por una Siuna y va al portal a A'ansur bajo el glaciar. En el combate final, el propio cuerpo de Indra llega para sujetar a Amashilama mientras Indra detona una bomba de la Brecha que acaba con ambas. Convertida en dron en Kiengir, Indra decide buscar la forma de devolver a Damu un cuerpo de verdad. Una escena secreta tras los créditos muestra a la Indra que se sacrificó reunida con Samara y Hammond."},
          WIKI "Indra", true},
    Entry{"link_av1", Kind::Timeline, {"Links to the first game", "Conexiones con el primer juego"},
          {"How Axiom Verge 2 connects to Sudra, the Rusalki and Athetos.",
           "Cómo se conecta Axiom Verge 2 con Sudra, los Rusalki y Athetos."},
          {"After the Udug War, the Sagiga's strongest Wielders pushed into Engur, the Udug's home, which became Absu; the survivors founded Sudra. Damu's drone infects humans with a disease that turns them into Proto-Xedur, a likely origin for the first game's pathogen. Many signs (Indra's love of Shakespeare, her final form, the final battle's music) suggest Indra becomes the Rusalka Ophelia. After the ending, Drushka teams up with Indra to reach A'ansur, which needs a PatternMind: the setup for the first game.",
           "Tras la guerra contra los Udug, los portadores más poderosos de los Sagiga entraron en Engur, el hogar de los Udug, que pasó a ser Absu; los supervivientes fundaron Sudra. El dron de Damu contagia a los humanos una enfermedad que los convierte en Proto-Xedur, un probable origen del patógeno del primer juego. Muchas señales (el gusto de Indra por Shakespeare, su forma final, la música del último combate) sugieren que Indra se convierte en la Rusalka Ophelia. Tras el final, Drushka se une a Indra para llegar a A'ansur, para lo que hace falta un PatternMind: el punto de partida del primer juego."},  // codespell:ignore hace,ser
          WIKI "Story", true},
};

#undef WIKI

} // namespace

std::span<const Entry> AxiomVerge2Entries() {
    return Entries;
}

const Game& AxiomVerge2() {
    static constexpr std::array kinds{Kind::All,  Kind::Place,   Kind::Character,
                                      Kind::Boss, Kind::Item,    Kind::Ability,
                                      Kind::Guide, Kind::Timeline};
    static const Game game{
        AxiomVerge2ProgramId,
        {"Axiom Verge 2", "Axiom Verge 2"},
        {"Explore Kiengir and the Breach by topic: lands, Arms, gear, tips, and the story. The big "
         "revelations stay hidden until you ask for spoilers.",
         "Explora Kiengir y la Brecha por temas: tierras, Arms, equipo, consejos e historia. Las "
         "grandes revelaciones quedan ocultas hasta que pidas spoilers."},
        {"Weapons and gear", "Armas y equipo"},
        AxiomVerge2Entries,
        kinds,
        nullptr,
        {"Arms (abilities)", "Arms (habilidades)"},
        {"Story and lore", "Historia y trasfondo"}};
    return game;
}

} // namespace GameCompanion
